// Обработка сообщения WM_SETCURSOR#include "stdafx.h"#include "MnemoWnd.h"#include "Queue.h"#include "QueueAPM.h"#include "QueueWnd.h"//-----------------------------------------------------------------------------#define DefineMouseS CQueueWnd* wnd,LPBYTE& szQueue,SQueue& q,POINT& point,int* pnNumber,bool bLButtonint MouseNullS(DefineMouseS)  {  return SkipQueue(szQueue);  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Подгружается только в режиме разработчика#define MACROS( EMPTY, STRUCT, NAME ) \int MouseS##EMPTY(DefineMouseS)\  {\  QueueM(STRUCT);\  return ( ::PtInRect( &p->mRect, point ) )? 0 : 1;\  }#include "Rect.hpp"//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция определенияint MouseOperators(DefineMouseS)  {  QueueM(Queue_Library);  if ( p->btSendType == QUEUE_LOGIC )    {    szQueue -= p->wdSizeOf;    (*p->paint)( NULL, szQueue, q, NULL, &wnd->mLogic );    return 1;    }  if ( wnd->mLogic.InVis() ) return 1;  if ( ::PtInRect( &p->mRect, point ) )    {    if ( bLButton )      {      if ( p->press )        {        wnd->m_pObject = p;        (*p->press)(q,p,point,0);        if ( wnd->mLogic.InVis() ) return 1;        }      }    if ( pnNumber ) *pnNumber = p->nNumber;    return 0;    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int MouseQueueS(CQueueWnd* wnd,SQueue& q,POINT point,int* nNumber,bool bLButton)  {  typedef int (*LPFuncMouse)(DefineMouseS);  static  LPFuncMouse gs_funcMouse[TYPE_UNKNOWN+1];  static bool bInit = true;  if ( bInit )    {    bInit=false;    for ( int n = 0; n < TYPE_UNKNOWN+1; n++ )      gs_funcMouse[n] = MouseNullS;    //    if ( ::IsMnemoStyle(MNEMO_HIDE_SCN|MNEMO_EDIT) )      {      #define MACROS( EMPTY, STRUCT, NAME  ) gs_funcMouse[EMPTY] = MouseS##EMPTY;      #include "Rect.hpp"      gs_funcMouse[TYPE_LIBRARY] = MouseOperators;      }    else      {      gs_funcMouse[TYPE_LIBRARY] = MouseOperators;      }    }  //  LPBYTE szQueue = q.Dyna.szQueue;  if ( szQueue )    {    //    int n = 0;    unsigned char type;    wnd->mLogic.Begin();    while ( gs_funcMouse[type = *szQueue](wnd,szQueue,q,point,nNumber,bLButton) ) n++;    if ( type != TYPE_NULL )    return (type != TYPE_NULL)?n:-1;    }  //  if ( ::IsMnemoStyle(MNEMO_HIDE_SCN) )    {    szQueue = q.Stat.szQueue;    if ( szQueue )      {      int n = 0;      unsigned char type;      wnd->mLogic.Begin();      while ( gs_funcMouse[type = *szQueue](wnd,szQueue,q,point,nNumber,false) ) n++;      return (type != TYPE_NULL)?1000000+n:-1;      }    }  //  return -1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~